/// <summary>
///
/// </summary>
public static METSalesOrderShipmentLoadHeader findOrCreateOpenShipment(CustAccount                    _custAccount,
                                                                      METRoute                        _metRoute,
                                                                      METRouteStopNum                 _metRouteStop,
                                                                      SalesShippingDateConfirmed      _confirmedDate,
                                                                      InventLocationId                _inventLocationId,
                                                                      MetOrderTransactionType         _transactionType,
                                                                      boolean                         _findAndCreate = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.CustAccount == _custAccount       &&
            metSalesOrderShipmentLoadHeader.Route == _metRoute                  &&
            metSalesOrderShipmentLoadHeader.RouteStopNum == _metRouteStop       &&
            metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate &&
            metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId      &&
            metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

    if (metSalesOrderShipmentLoadHeader.RecId != 0 || _findAndCreate == false)
    {
        return metSalesOrderShipmentLoadHeader;
    }

    metSalesOrderShipmentLoadHeader.clear();

    metSalesOrderShipmentLoadHeader.ShipmentId      = NumberSeq::newGetNum(InventParameters::numRefMetShippingID()).num();
    metSalesOrderShipmentLoadHeader.CustAccount     = _custAccount;
    metSalesOrderShipmentLoadHeader.ConfirmedShipDate = _confirmedDate;
    metSalesOrderShipmentLoadHeader.Route           = _metRoute;
    metSalesOrderShipmentLoadHeader.RouteStopNum    = _metRouteStop;
    metSalesOrderShipmentLoadHeader.Warehouse       = _inventLocationId;
    metSalesOrderShipmentLoadHeader.SiteId          = InventLocation::find(_inventLocationId).InventSiteId;
    metSalesOrderShipmentLoadHeader.TransactionType = _transactionType;
    metSalesOrderShipmentLoadHeader.ShipmentStatus  = MetShipmentStatus::Open;
    metSalesOrderShipmentLoadHeader.ShipmentCarrier = '';
    metSalesOrderShipmentLoadHeader.ShipmentLoad    = METShipmentLoad::Shipment;
    metSalesOrderShipmentLoadHeader.insert();


    return metSalesOrderShipmentLoadHeader;
}

public static METSalesOrderShipmentLoadHeader findOrCreateOpenLoad(METRoute                     _metRoute,
                                                                SalesShippingDateConfirmed      _confirmedDate,
                                                                InventLocationId                _inventLocationId,
                                                                MetOrderTransactionType         _transactionType,
                                                                boolean                         _findAndCreate = false)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.Route == _metRoute                    &&
            metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate     &&
            metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId          &&
            metSalesOrderShipmentLoadHeader.LoadStatus == METLoadStatus::Open;

    if (metSalesOrderShipmentLoadHeader.RecId != 0 || _findAndCreate == false)
    {
        return metSalesOrderShipmentLoadHeader;
    }

    metSalesOrderShipmentLoadHeader.clear();

    metSalesOrderShipmentLoadHeader.LoadId          = NumberSeq::newGetNum(InventParameters::numRefMetLoadID()).num();
    metSalesOrderShipmentLoadHeader.Route           = _metRoute;
    metSalesOrderShipmentLoadHeader.Warehouse       = _inventLocationId;
    metSalesOrderShipmentLoadHeader.SiteId          = InventLocation::find(_inventLocationId).InventSiteId;
    metSalesOrderShipmentLoadHeader.TransactionType = _transactionType;
    metSalesOrderShipmentLoadHeader.LoadStatus      = MetLoadStatus::Open;
    metSalesOrderShipmentLoadHeader.ShipmentLoad    = METShipmentLoad::Shipment;
    metSalesOrderShipmentLoadHeader.ConfirmedShipDate = _confirmedDate;
    metSalesOrderShipmentLoadHeader.insert();



    return metSalesOrderShipmentLoadHeader;
}

public static void generateShipmentLoadFromExtraction(container         _soListFromExtraction,
                                                    boolean             _createShipment)
{
    SalesTable                                  salesTable;
    METSalesOrderShipmentLoadCreationTmp        tmpTable;
    METSalesOrderShipmentLoadHeader             salesOrderShipmentLoadHeader;

    for (int i = 1; i <= conLen(_soListFromExtraction); i++)
    {
        salesTable = SalesTable::find(conPeek(_soListFromExtraction, i));

        if (salesTable.RecId)
        {
            tmpTable.clear();

            tmpTable.RouteStopNum = salesTable.METRouteStopNum;
            tmpTable.CustAccount = salesTable.CustAccount;
            tmpTable.ConfirmedShipDate = salesTable.ShippingDateConfirmed;
            tmpTable.SiteId = salesTable.InventSiteId;
            tmpTable.Warehouse = salesTable.InventLocationId;
            tmpTable.Route = salesTable.METRoute;

            tmpTable.insert();
        }
    }

    //Shipment creation and update
    while select tmpTable
        group by CustAccount, ConfirmedShipDate, Warehouse, RouteStopNum, Route
    {
        salesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findOrCreateOpenShipment(tmpTable.CustAccount,
                                                                                                tmpTable.Route,
                                                                                                tmpTable.RouteStopNum,
                                                                                                tmpTable.ConfirmedShipDate,
                                                                                                tmpTable.Warehouse,
                                                                                                METOrderTransactionType::SalesOrder,
                                                                                                _createShipment);
        if (salesOrderShipmentLoadHeader.RecId)
        {
            METSalesOrderShipmentLoadLines::createShipmentLines(salesOrderShipmentLoadHeader);

            if (_createShipment)
            {
                info(strFmt("Shipment %1 is created.", salesOrderShipmentLoadHeader.ShipmentId));
            }
            else
            {
                info(strFmt("Shipment %1 is updated.", salesOrderShipmentLoadHeader.ShipmentId));
            }
        }
    }

    //Load creation and update
    while select tmpTable
        group by ConfirmedShipDate, Warehouse, Route
    {
        salesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findOrCreateOpenLoad(tmpTable.Route,
                                                                                            tmpTable.ConfirmedShipDate,
                                                                                            tmpTable.Warehouse,
                                                                                            METOrderTransactionType::SalesOrder,
                                                                                            _createShipment);
        if (salesOrderShipmentLoadHeader.RecId)
        {
            METSalesOrderShipmentLoadLines::createLoadLines(salesOrderShipmentLoadHeader);

            if (_createShipment)
            {
                info(strFmt("Load %1 is created.", salesOrderShipmentLoadHeader.LoadId));
            }
            else
            {
                info(strFmt("Load %1 is updated.", salesOrderShipmentLoadHeader.LoadId));
            }
        }
    }
}
